rungs.generators-outside-gauge-algebra:
"""rungs.generators-outside-gauge-algebra: exact checks.

The composite's five modes (three pair modes, two rung/slot modes) as the 32-dimensional Fock module,
exact rational matrices (Jordan-Wigner). The ten Majoranas are g_{2m} = v_m + w_m, g_{2m+1} = w_m - v_m
(the text's gamma_{2m+1} is I g_{2m+1} with I central, so complex spans agree); the 45 bilinears
g_p g_q span so(10). The counts are kernel dimensions of linear maps on that span, computed as
45 - rank of the images (the bilinears are independent):
(1) ad N (N the total mode number) has a 25-dimensional kernel, spanned by v_i w_j (i != j) and
    n_i - 1/2: u(5); the other 20 bilinear directions v_i v_j, w_i w_j have [N, X] = +-2X.
(2) ad N_R and ad N_W jointly have a 13-dimensional kernel, spanned by the v_a w_b with a, b both rungs
    or both pairs (4 + 9): u(2) + u(3).
(3) The 12 = 25 - 13 directions v_a w_b with one rung and one pair index have [N_R, X] = +-X and
    [N_W, X] = -+X: one excitation moves between a rung and a pair. 45 - 13 = 32 lie outside.
The five-mode CAR is Hypothesis (S)'s clause (v) (or the rung reading (R), which gives the same module);
the span of the bilinears being so(10) is the imported Bogoliubov Fact.
"""
from fractions import Fraction as F

import GA
from pyutil import get_or_set
import fock
from tp_premise import premise

# ---------------------------------------------------------------------------
# The five-mode module Lambda(W + R_2) = Lambda(C^5), exact.
# States are bitmasks s in 0..31; mode m is occupied when bit m is set.
# Modes 0, 1, 2 are the three pair modes (W), modes 3, 4 the two slot (rung)
# modes, the text's modes 4 and 5. Operators are sparse matrices
# {(row, col): Fraction}; Jordan-Wigner sign (-1)^(occupied modes below m).
# ---------------------------------------------------------------------------
NM = 5
DIM = 32
PAIRS = (0, 1, 2)
SLOTS = (3, 4)


def nw(s):
    return sum(1 for m in PAIRS if s >> m & 1)


def nr(s):
    return sum(1 for m in SLOTS if s >> m & 1)


def ntot(s):
    return nw(s) + nr(s)


def create(m):
    return fock.cre(m, NM)


# sparse exact operators from lib/fock.py (LSB order; comm and acomm are not halved); tr is the TRANSPOSE
tr = fock.transpose
mm, madd, msc, msub = fock.mm, fock.madd, fock.msc, fock.msub
comm, acomm, meq = fock.comm, fock.acomm, fock.meq
restrict = fock.restrict


ONE = fock.eye(DIM)
V = [create(m) for m in range(NM)]          # v_m, creation
W = [tr(v) for v in V]                      # w_m, annihilation
NUM = [fock.num(m, NM) for m in range(NM)]   # n_m


def gam(p):
    """Majorana p = 0..9 of mode p // 2 in the real form: gamma_{2m} = v_m + w_m (square +1),
    g_{2m+1} = w_m - v_m (square -1). The text's gamma_{2m+1} = I g_{2m+1}, I^2 = -1 central."""
    return fock.majorana(p, NM)


class Span:
    """Incremental exact span of sparse vectors (dicts with hashable keys), reduced row echelon."""

    def __init__(self):
        self.piv, self.where = {}, {}

    def reduce(self, v):
        v = {k: x for k, x in v.items() if x}
        for k in [k for k in v if k in self.piv]:
            c = v.pop(k)
            for kk, xx in self.piv[k].items():
                if kk != k:
                    y = v.get(kk, 0) - c * xx
                    if y:
                        v[kk] = y
                    else:
                        v.pop(kk, None)
        return v

    def add(self, v):
        v = self.reduce(v)
        if not v:
            return False
        k0 = next(iter(v))
        c0 = v[k0]
        v = {k: x / c0 for k, x in v.items()}
        for p in list(self.where.get(k0, ())):
            row = self.piv[p]
            c = row.pop(k0)
            for kk, xx in v.items():
                if kk != k0:
                    y = row.get(kk, 0) - c * xx
                    if y:
                        row[kk] = y
                        get_or_set(self.where, kk, set()).add(p)
                    else:
                        row.pop(kk, None)
                        self.where.get(kk, set()).discard(p)
        self.where.pop(k0, None)
        self.piv[k0] = v
        for kk in v:
            if kk != k0:
                get_or_set(self.where, kk, set()).add(k0)
        return True

    def __len__(self):
        return len(self.piv)


def rank(vecs):
    """Exact rank of sparse vectors (dicts with hashable keys)."""
    sp = Span()
    for v in vecs:
        sp.add(v)
    return len(sp)


def in_span(vecs, v):
    sp = Span()
    for u in vecs:
        sp.add(u)
    return not sp.reduce(v)


def bilinears():
    """The 45 products g_p g_q, p < q, of the real-form Majoranas (the bivectors of the ten,
    up to the central factors of I)."""
    G = [gam(p) for p in range(2 * NM)]
    return {(p, q): mm(G[p], G[q]) for p in range(2 * NM) for q in range(p + 1, 2 * NM)}


def commutant_dim(gens, states):
    """Dimension of {X on span(states) : [X, g] = 0 for all g}, by exact sparse elimination."""
    S = list(states)
    Sset = set(S)
    rows = []
    for g in gens:
        g = restrict(g, S)
        grow, gcol = {}, {}
        for (r, c), x in g.items():
            get_or_set(grow, r, []).append((c, x))
            get_or_set(gcol, c, []).append((r, x))
        for r in S:
            for c in S:
                eq = {}
                # (X g)_{rc} = sum_k X_{rk} g_{kc};  (g X)_{rc} = sum_k g_{rk} X_{kc}
                for k, x in gcol.get(c, ()):
                    eq[(r, k)] = eq.get((r, k), 0) + x
                for k, x in grow.get(r, ()):
                    eq[(k, c)] = eq.get((k, c), 0) - x
                eq = {k: x for k, x in eq.items() if x}
                if eq:
                    rows.append(eq)
    return len(S) * len(S) - rank(rows)


def nr_op():
    return madd(NUM[3], NUM[4])


def nw_op():
    return madd(NUM[0], NUM[1], NUM[2])


def check_mode_number_preserving_is_u5():
    premise("rungs.imported-fock-representation-bogoliubov-group")
    premise("standard-model.hyp-s-slot-statistics")
    B = list(bilinears().values())
    N = madd(nr_op(), nw_op())
    ok = rank(B) == 45
    kernel = 45 - rank([comm(N, X) for X in B])
    ok = ok and kernel == 25
    u5 = [mm(V[i], W[j]) for i in range(NM) for j in range(NM) if i != j]
    u5 += [msub(NUM[i], msc(F(1, 2), ONE)) for i in range(NM)]
    ok = ok and len(u5) == 25 and rank(u5) == 25
    ok = ok and rank(B + u5) == 45                      # inside the span of the bilinears
    ok = ok and all(not comm(N, X) for X in u5)         # inside the kernel, so they span it
    changing = [mm(V[i], V[j]) for i in range(NM) for j in range(i + 1, NM)]
    changing += [mm(W[i], W[j]) for i in range(NM) for j in range(i + 1, NM)]
    ok = ok and len(changing) == 20 and rank(B + changing) == 45 and rank(u5 + changing) == 45
    ok = ok and all(meq(comm(N, X), msc(2, X)) for X in changing[:10])
    ok = ok and all(meq(comm(N, X), msc(-2, X)) for X in changing[10:])
    GA.check("25 of the 45 preserve the mode number (u(5)); 20 change it by two", ok)
    return ok


def check_split_preserving_is_u2_u3():
    premise("rungs.imported-fock-representation-bogoliubov-group")
    premise("standard-model.hyp-s-slot-statistics")
    B = list(bilinears().values())
    NR, NW = nr_op(), nw_op()
    images = [madd({("R",) + k: x for k, x in comm(NR, X).items()},
                   {("W",) + k: x for k, x in comm(NW, X).items()}) for X in B]
    kernel = 45 - rank(images)
    ok = kernel == 13
    blocks = [(a, b) for a in SLOTS for b in SLOTS] + [(a, b) for a in PAIRS for b in PAIRS]
    u23 = [mm(V[a], W[b]) if a != b else msub(NUM[a], msc(F(1, 2), ONE)) for a, b in blocks]
    ok = ok and len(u23) == 13 and rank(u23) == 13 and rank(B + u23) == 45
    ok = ok and all(not comm(NR, X) and not comm(NW, X) for X in u23)
    cross = [mm(V[a], W[b]) for a in SLOTS for b in PAIRS] + [mm(V[b], W[a]) for a in SLOTS for b in PAIRS]
    ok = ok and len(cross) == 12 and rank(u23 + cross) == 25
    # v_rung w_pair raises N_R by one and lowers N_W by one, and conversely
    ok = ok and all(meq(comm(NR, X), X) and meq(comm(NW, X), msc(-1, X)) for X in cross[:6])
    ok = ok and all(meq(comm(NR, X), msc(-1, X)) and meq(comm(NW, X), X) for X in cross[6:])
    ok = ok and 45 - kernel == 32
    GA.check("13 preserve the slot-pair split and the mode number (u(2) + u(3)); 12 move one excitation", ok)
    return ok

rungs.imported-tower-one-qubit-per-rung:
"""rungs.imported-tower-one-qubit-per-rung: exact checks.

Floors T_k = Cl(p+k, q+k) in GA.py (ground generators first, then plane j as e_j (+1), f_j (-1);
v_j = (e_j + f_j)/2, w_j = (e_j - f_j)/2). The Fock module Lambda W_k is the occupation basis with
v_j by wedge and w_j by contraction (Jordan-Wigner signs). Checked, on the instances listed:
(1) the CAR as vector identities in T_k, k = 1, 2, 3, over the grounds (1,3), (0,0), (2,1);
(2) the commuting copies, k = 1, 2, over (1,3), (1,1), (0,2): the twisted ground generators
    x omega_1 ... omega_k satisfy the ground relations and commute with the 2k plane generators,
    whose words span 4^k dimensions, and A-words times B-words are 2^(n+2k) distinct blades, so
    multiplication A_k (x) B_k -> T_k is an isomorphism;
(3) the Fock module, k = 1, 2, 3: the plane generators act with the Clifford relations of
    Cl(k,k) and their 4^k words act as a basis of End(Lambda W_k) (so the module is irreducible
    and B_k = Mat_{2^k}(R)); the vacuum is annihilated by every w_j and cyclic for the v_j; each
    rung doubles the module, the operators of the first k planes acting by one and the same block
    on the two halves v_{k+1}-absent and v_{k+1}-present;
(4) the Witt index: min(p,q) + k anticommuting mode pairs built from vectors of T_k for k = 0..3
    over (1,3), (2,0), (0,0), (3,1), their creation span totally isotropic of that dimension, which
    equals min(n_+, n_-) of the floor's form (computed by congruence): one more per rung. That no
    family of vectors does better is Witt's bound on isotropic subspaces, not recomputed;
(5) the *-structure on the real form of T_1 over (1,1), (0,2) and T_2 over (0,0): the
    antiautomorphism generated by x* = x (x^2 = 1), x* = -x (x^2 = -1) is computed blade by blade
    as the reversed product (so it is unique), is antimultiplicative on all blade pairs and
    involutive, makes every blade unitary, and gives v_j* = w_j. Conjugate-linearity is the
    extension to complex coefficients and is not separately computed.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from pyutil import get_or_set
from tp_premise import premise

# ---------------------------------------------------------------------------
# Exact Clifford helpers on top of GA.py (elements are dicts {blade: Fraction}).
# ---------------------------------------------------------------------------


def blade_el(b, c=1):
    return {tuple(b): F(c)} if c else {}


def prod(xs, sq):
    out = GA.sc(1)
    for x in xs:
        out = GA.mul(out, x, sq)
    return out


def coords(x, n):
    return [x.get(b, F(0)) for b in GA.all_blades(n)]


def span_rank(els, n):
    els = [e for e in els if not GA.is_zero(e)]
    return GA.rank_of_vectors([coords(e, n) for e in els]) if els else 0


def words(gens, sq):
    """The ordered products of all subsets of gens: they span the generated subalgebra
    when the generators pairwise anticommute and square to nonzero scalars."""
    out = []
    for r in range(len(gens) + 1):
        for idx in combinations(range(len(gens)), r):
            out.append(prod([gens[i] for i in idx], sq))
    return out


def scalar_of(x):
    """x as a scalar if it is one, else None."""
    if GA.is_zero(x):
        return F(0)
    if set(x) == {()}:
        return x[()]
    return None


def anticommuting_with_squares(gens, sq):
    """The list of squares if the gens pairwise anticommute and square to scalars, else None."""
    out = []
    for i, g in enumerate(gens):
        s = scalar_of(GA.mul(g, g, sq))
        if s is None:
            return None
        out.append(s)
        for h in gens[i + 1:]:
            if not GA.anticommutes(g, h, sq):
                return None
    return out


def volume(n, sq):
    return prod([GA.gen(i) for i in range(n)], sq)


def is_central(x, n, sq):
    return all(GA.commutes(x, GA.gen(i), sq) for i in range(n))


def corner(f, basis, sq, n):
    """An independent spanning list of f b f, b in basis."""
    out, vecs = [], []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if GA.is_zero(y):
            continue
        v = coords(y, n)
        if GA.rank_of_vectors(vecs + [v]) > len(vecs):
            vecs.append(v)
            out.append(y)
    return out


def corner_division_type(f, basis, sq, n):
    """'R', 'C' or 'H' when f is an idempotent whose corner f A f is that division algebra
    (exact: R = span{f}; C = f plus an element squaring to -f; H = quaternion units i, j,
    i j with i^2 = j^2 = -f, i j = -j i), else None. A division corner makes f primitive,
    so the letter is the Wedderburn division algebra of the simple algebra A."""
    if not GA.eq(GA.mul(f, f, sq), f):
        return None
    cb = corner(f, basis, sq, n)
    if len(cb) == 1:
        return "R"
    roots = []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if not GA.is_zero(y) and GA.eq(GA.mul(y, y, sq), GA.neg(f)):
            roots.append(y)
    if len(cb) == 2 and roots:
        return "C"
    if len(cb) == 4:
        for i, a in enumerate(roots):
            for c in roots[i + 1:]:
                if GA.is_zero(GA.add(GA.mul(a, c, sq), GA.mul(c, a, sq))):
                    if span_rank([f, a, c, GA.mul(a, c, sq)], n) == 4:
                        return "H"
    return None


def idempotent_from(us, sq):
    """prod (1 + u)/2 over commuting elements u with u^2 = 1."""
    f = GA.sc(1)
    for u in us:
        f = GA.mul(f, GA.scal(F(1, 2), GA.add(GA.sc(1), u)), sq)
    return f


def simple_copy_type(gens, sq, n):
    """For a simple subalgebra spanned by words(gens): (k, D) with the subalgebra Mat_k(D),
    found from an idempotent f = prod (1 + u)/2 (u words squaring to 1, commuting) whose corner
    is a division algebra; dim = k^2 dim D is asserted. None if no such f is found."""
    basis = words(gens, sq)
    dim = span_rank(basis, n)
    units = [u for u in basis if scalar_of(u) is None and GA.eq(GA.mul(u, u, sq), GA.sc(1))]
    trials = [[]] + [[u] for u in units]
    trials += [[u, v] for i, u in enumerate(units) for v in units[i + 1:] if GA.commutes(u, v, sq)]
    for us in trials:
        f = idempotent_from(us, sq)
        if GA.is_zero(f):
            continue
        d = corner_division_type(f, basis, sq, n)
        if d is None:
            continue
        dd = {"R": 1, "C": 2, "H": 4}[d]
        k = 1
        while k * k * dd < dim:
            k += 1
        assert k * k * dd == dim
        return (k, d)
    return None
# ---------------------------------------------------------------------------
# Floors of the tower in GA.py: T_k over Cl(p,q) has the ground generators 0..n-1 (p squares +1,
# then q squares -1) and plane j (0-based) at n + 2j (e_j, square +1), n + 2j + 1 (f_j, square -1).
# v_j = (e_j + f_j)/2, w_j = (e_j - f_j)/2, omega_j = e_j f_j, Omega_k = omega_1 ... omega_k.
# ---------------------------------------------------------------------------


def floor_sq(p, q, k):
    return tuple([1] * p + [-1] * q + [1, -1] * k)


def plane(n, j):
    e, f = GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1)
    return GA.scal(F(1, 2), GA.add(e, f)), GA.scal(F(1, 2), GA.sub(e, f))


def big_omega(n, k, sq):
    return prod([GA.mul(GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1), sq) for j in range(k)], sq)


def twisted_ground(n, k, sq):
    Om = big_omega(n, k, sq)
    return [GA.mul(GA.gen(i), Om, sq) for i in range(n)]


def matrix_units(n, k, sq):
    """E[(S, T)] = v_S f v_T^dagger, S, T subsets of the k planes, f = prod_j w_j v_j the vacuum
    projector and v_T^dagger the reversed product of the w's; the Fock-basis matrix units of B_k."""
    vs, ws = zip(*[plane(n, j) for j in range(k)]) if k else ((), ())
    f = prod([GA.mul(ws[j], vs[j], sq) for j in range(k)], sq)
    subsets = [S for r in range(k + 1) for S in combinations(range(k), r)]
    E = {}
    for S in subsets:
        left = prod([vs[j] for j in S], sq)
        for T in subsets:
            right = prod([ws[j] for j in reversed(T)], sq)
            E[(S, T)] = GA.mul(GA.mul(left, f, sq), right, sq)
    return subsets, E


def matrix_units_ok(subsets, E, sq):
    one = GA.add(*[E[(S, S)] for S in subsets])
    if not GA.eq(one, GA.sc(1)):
        return False
    for (S, T), x in E.items():
        for (U, W), y in E.items():
            want = E[(S, W)] if T == U else {}
            if not GA.eq(GA.mul(x, y, sq), want):
                return False
    return True


def tensor_blades(gens_a, gens_b, sq):
    """Products of the ordered words of gens_a with those of gens_b, when every one is a single
    basis blade: the set of blades hit (None if some product is not a single blade)."""
    seen = set()
    for a in words(gens_a, sq):
        for b in words(gens_b, sq):
            x = GA.mul(a, b, sq)
            if len(x) != 1:
                return None
            seen.add(next(iter(x)))
    return seen
# ---------------------------------------------------------------------------
# The Fock module Lambda W_k in the occupation basis: states are bitmasks 0 .. 2^k - 1, bit j set
# when v_j is present; the wedge monomial basis v_{j1} ^ ... ^ v_{jr} (j1 < ... < jr) is
# orthonormal. v_j acts by wedge (sign (-1)^(occupied modes below j)), w_j by contraction.
# Operators are sparse matrices {(row, col): Fraction}.
# ---------------------------------------------------------------------------


def k_wedge(j, k):
    return {(s | 1 << j, s): F((-1) ** bin(s & ((1 << j) - 1)).count("1"))
            for s in range(2 ** k) if not s >> j & 1}


def k_contract(j, k):
    return {(s & ~(1 << j), s): F((-1) ** bin(s & ((1 << j) - 1)).count("1"))
            for s in range(2 ** k) if s >> j & 1}


def smm(*Ms):
    out = Ms[0]
    for B in Ms[1:]:
        rows = {}
        for (r, c), x in B.items():
            get_or_set(rows, r, []).append((c, x))
        acc = {}
        for (r, t), x in out.items():
            for c, y in rows.get(t, ()):
                acc[(r, c)] = acc.get((r, c), 0) + x * y
        out = {key: v for key, v in acc.items() if v}
    return out


def sadd(*Ms):
    acc = {}
    for M in Ms:
        for key, x in M.items():
            acc[key] = acc.get(key, 0) + x
    return {key: v for key, v in acc.items() if v}


def ssc(c, A):
    return {key: c * x for key, x in A.items() if c * x}


def str_(A):
    return {(c, r): x for (r, c), x in A.items()}


def sident(d):
    return {(s, s): F(1) for s in range(d)}


def plane_images(k):
    """rho(e_j) = wedge + contraction, rho(f_j) = wedge - contraction, in GA generator order."""
    out = []
    for j in range(k):
        a, b = k_wedge(j, k), k_contract(j, k)
        out += [sadd(a, b), sadd(a, ssc(-1, b))]
    return out


def flat(M, d):
    return [M.get((r, c), F(0)) for r in range(d) for c in range(d)]

CAR_GROUNDS = [(1, 3), (0, 0), (2, 1)]
COPY_GROUNDS = [(1, 3), (1, 1), (0, 2)]
WITT_GROUNDS = [(1, 3), (2, 0), (0, 0), (3, 1)]
STAR_FLOORS = [(1, 1, 1), (0, 2, 1), (0, 0, 2)]


def car_ok(vs, ws, sq):
    ok = True
    for i in range(len(vs)):
        for j in range(len(vs)):
            ok = ok and GA.is_zero(GA.add(GA.mul(vs[i], vs[j], sq), GA.mul(vs[j], vs[i], sq)))
            ok = ok and GA.is_zero(GA.add(GA.mul(ws[i], ws[j], sq), GA.mul(ws[j], ws[i], sq)))
            ac = GA.add(GA.mul(vs[i], ws[j], sq), GA.mul(ws[j], vs[i], sq))
            ok = ok and GA.eq(ac, GA.sc(1) if i == j else {})
    return ok


CAR_RUNGS = (1, 2, 3)


def _acomm(x, y, sq):
    return GA.add(GA.mul(x, y, sq), GA.mul(y, x, sq))


def check_ladder_pairs_satisfy_car():
    premise("tower.ladder-pairs-satisfy-car-vectors")
    ok = True
    for p, q in CAR_GROUNDS:
        for k in CAR_RUNGS:
            sq = floor_sq(p, q, k)
            n = p + q
            # T_k = Cl(p+k, q+k): p + k generators of square +1 and q + k of square -1
            ok = ok and sq.count(1) == p + k and sq.count(-1) == q + k
            vs, ws = zip(*[plane(n, j) for j in range(k)])
            for i in range(k):
                for j in range(k):
                    ok = ok and GA.is_zero(_acomm(vs[i], vs[j], sq)) and GA.is_zero(_acomm(ws[i], ws[j], sq))
                    ok = ok and GA.eq(_acomm(vs[i], ws[j], sq), GA.sc(F(1)) if i == j else {})
                # By hand, with e^2 = 1, f^2 = -1: v w = (e^2 - e f + f e - f^2)/4 = (1 - e f)/2 and
                # w v = (1 + e f)/2, two complementary idempotents.
                ef = GA.mul(GA.gen(n + 2 * i), GA.gen(n + 2 * i + 1), sq)
                ok = ok and GA.eq(GA.mul(vs[i], ws[i], sq), GA.scal(F(1, 2), GA.sub(GA.sc(F(1)), ef)))
                ok = ok and GA.eq(GA.mul(ws[i], vs[i], sq), GA.scal(F(1, 2), GA.add(GA.sc(F(1)), ef)))
    GA.check("v_i v_j + v_j v_i = 0, w_i w_j + w_j w_i = 0, v_i w_j + w_j v_i = delta_ij, k <= 3", ok)
    return ok


def check_commuting_copies():
    premise("tower.commuting-copies")
    ok = True
    for p, q in COPY_GROUNDS:
        n = p + q
        for k in (1, 2):
            sq = floor_sq(p, q, k)
            tw = twisted_ground(n, k, sq)
            pg = [GA.gen(n + i) for i in range(2 * k)]
            ok = ok and anticommuting_with_squares(tw, sq) == [1] * p + [-1] * q
            ok = ok and anticommuting_with_squares(pg, sq) == [1, -1] * k
            ok = ok and all(GA.commutes(x, y, sq) for x in tw for y in pg)
            ok = ok and span_rank(words(pg, sq), n + 2 * k) == 4 ** k
            hit = tensor_blades(tw, pg, sq)
            ok = ok and hit is not None and len(hit) == 2 ** (n + 2 * k)
    GA.check("A_k = Cl(p,q) twisted and B_k = Cl(k,k) commute and multiply onto T_k, k = 1, 2", ok)
    return ok


def check_fock_module_one_qubit_per_rung():
    premise("tower.fock-module-one-qubit-per-rung")
    ok = True
    for k in (1, 2, 3):
        d = 2 ** k
        rho = plane_images(k)
        sqs = [1, -1] * k
        one = sident(d)
        for a in range(2 * k):
            ok = ok and smm(rho[a], rho[a]) == ssc(sqs[a], one)
            for b in range(a + 1, 2 * k):
                ok = ok and not sadd(smm(rho[a], rho[b]), smm(rho[b], rho[a]))
        imgs = []
        for r in range(2 * k + 1):
            for B in combinations(range(2 * k), r):
                imgs.append(flat(smm(*([one] + [rho[i] for i in B])), d))
        ok = ok and len(imgs) == 4 ** k and GA.rank_of_vectors(imgs) == d * d
        # vacuum: killed by every w_j, cyclic for the v_j
        vac = {(0, 0): F(1)}
        ok = ok and all(not smm(k_contract(j, k), vac) for j in range(k))
        states = set()
        for r in range(k + 1):
            for S in combinations(range(k), r):
                x = vac
                for j in reversed(S):
                    x = smm(k_wedge(j, k), x)
                states |= {row for (row, _c) in x}
        ok = ok and states == set(range(d))
        # one qubit per rung: on Lambda W_{k+1} the first k planes act by the same block on both halves
        big = plane_images(k + 1)
        for a in range(2 * k):
            blk0 = {(r, c): x for (r, c), x in big[a].items() if r < d and c < d}
            blk1 = {(r - d, c - d): x for (r, c), x in big[a].items() if r >= d and c >= d}
            cross = [key for key in big[a] if (key[0] < d) != (key[1] < d)]
            ok = ok and blk0 == rho[a] and blk1 == rho[a] and not cross
    GA.check("Lambda W_k irreducible for B_k = Mat_{2^k}(R), vacuum cyclic, one qubit per rung, k <= 3", ok)
    return ok


def check_witt_index_one_per_rung():
    premise("tower.witt-index-quantum-capacity")
    ok = True
    for p, q in WITT_GROUNDS:
        n = p + q
        caps = []
        for k in range(4):
            sq = floor_sq(p, q, k)
            m = len(sq)
            npos, nneg, nz = GA.congruence_signature([[F(sq[i]) if i == j else F(0) for j in range(m)]
                                                      for i in range(m)])
            vs, ws = [], []
            for a in range(min(p, q)):
                xp, xm = GA.gen(a), GA.gen(p + a)
                vs.append(GA.scal(F(1, 2), GA.add(xp, xm)))
                ws.append(GA.scal(F(1, 2), GA.sub(xp, xm)))
            for j in range(k):
                v, w = plane(n, j)
                vs.append(v)
                ws.append(w)
            ok = ok and car_ok(vs, ws, sq)
            ok = ok and GA.rank_of_vectors([[x.get((i,), F(0)) for i in range(m)] for x in vs]) == len(vs)
            ok = ok and len(vs) == min(npos, nneg) and nz == 0
            caps.append(len(vs))
        ok = ok and [caps[i + 1] - caps[i] for i in range(3)] == [1, 1, 1]
    GA.check("min(p,q) + k anticommuting mode pairs by vectors, the Witt index, rising by one per rung", ok)
    return ok


def star_blade(b, sq):
    """The antiautomorphism with x* = x for x^2 = 1, x* = -x for x^2 = -1, on a blade: the
    reversed product of the starred generators."""
    out = GA.sc(1)
    for i in reversed(b):
        out = GA.mul(out, GA.scal(sq[i], GA.gen(i)), sq)
    return out


def star(x, sq):
    return GA.add(*[GA.scal(c, star_blade(b, sq)) for b, c in x.items()]) if x else {}


def check_star_structure():
    premise("tower.structure-tower-c-norms")
    ok = True
    for p, q, k in STAR_FLOORS:
        n = p + q
        m = n + 2 * k
        sq = floor_sq(p, q, k)
        blades = [blade_el(b) for b in GA.all_blades(m)]
        for b in GA.all_blades(m):
            r = len(b)
            nneg = sum(1 for i in b if sq[i] < 0)
            ok = ok and GA.eq(star_blade(b, sq), blade_el(b, (-1) ** (r * (r - 1) // 2 + nneg)))
        for x in blades:
            ok = ok and GA.eq(star(star(x, sq), sq), x)
            ok = ok and GA.eq(GA.mul(star(x, sq), x, sq), GA.sc(1))
            for y in blades:
                ok = ok and GA.eq(star(GA.mul(x, y, sq), sq), GA.mul(star(y, sq), star(x, sq), sq))
        for j in range(k):
            v, w = plane(n, j)
            ok = ok and GA.eq(star(v, sq), w) and GA.eq(star(w, sq), v)
    GA.check("the *-antiautomorphism is unique, involutive, makes blades unitary and gives v_j* = w_j", ok)
    return ok

rungs.ladder-group-rung-mixing-group-one:
"""rungs.ladder-group-rung-mixing-group-one: exact checks.

Fock model of the n-th rung's module, n = 1, 2, 3: modes 0..n-1 are the new rung modes v_1..v_n, modes
n..n+2 the three old pairs of W; Jordan-Wigner creation and annihilation operators act on basis states
(bitmasks) with exact integer signs, a basis state being a^dag_(m1) ... a^dag_(mk) |0> with m1 < ... < mk, so
the state with rung r and pair set S is e_r (x) f_S (the wedge basis of Lambda W in the same order). The
rung-mixing generator of X in gl(n) (the complexification of u(n)) is sum X_rs a^dag_r a_s over the rung
modes, the pair-mixing generator of Y in gl(3) the same over the pair modes.
(1) On the sector Lambda^1 R_n (x) Lambda^even W = C^n (x) CS, for every elementary X the rung-mixing
    operator equals X (x) 1 (the ladder action U (x) 1 on the n-tuple of conformal spinors), exactly, and
    nothing leaves the sector.
(2) For every elementary Y the pair-mixing operator acts on the same sector as 1 (x) Lambda^even(Y),
    with Lambda^even(Y) the derivation on the wedge basis computed independently of the Fock signs.
"""
from fractions import Fraction as F  # noqa: F401
from itertools import combinations

import GA  # noqa: F401
import fock
from tp_premise import premise

RUNGS = [1, 2, 3]


# a_i^dag, a_i on sparse Fock states {bitmask: coefficient} (LSB, Jordan-Wigner) and their sum, from lib/fock.py
cre, ann, st_add = fock.cre_on, fock.ann_on, fock.vadd


def bilinear(X, modes, st):
    """sum_rs X_rs a^dag_(modes r) a_(modes s) on a Fock state."""
    terms = []
    for r in range(len(modes)):
        for s in range(len(modes)):
            if X[r][s]:
                terms.append({b: X[r][s] * c for b, c in cre(modes[r], ann(modes[s], st)).items()})
    return st_add(*terms) if terms else {}


def mask(modes):
    return sum(1 << m for m in modes)


def _wedge(seq):
    if len(set(seq)) < len(seq):
        return 0, None
    seq = list(seq)
    sign = 1
    for i in range(len(seq)):
        for j in range(len(seq) - 1 - i):
            if seq[j] > seq[j + 1]:
                seq[j], seq[j + 1] = seq[j + 1], seq[j]
                sign = -sign
    return sign, tuple(seq)


def derive(Y, S):
    out = {}
    for t, s in enumerate(S):
        for r in range(len(Y)):
            if Y[r][s]:
                sg, T = _wedge(S[:t] + (r,) + S[t + 1:])
                if sg:
                    out[T] = out.get(T, 0) + sg * Y[r][s]
    return {T: c for T, c in out.items() if c}


def unit(n, i, j):
    return [[1 if (a, b) == (i, j) else 0 for b in range(n)] for a in range(n)]


def sector(n):
    """(r, S, Fock state) for one rung mode r and an even pair set S."""
    out = []
    for r in range(n):
        for k in (0, 2):
            for S in combinations(range(3), k):
                out.append((r, S, {mask([r] + [n + a for a in S]): 1}))
    return out


def check_rung_mixing_is_the_ladder_action():
    premise("rungs.imported-ladder-automorphism-group-no-lepton")
    premise("rungs.rung-spinor-module-mixings")
    ok = True
    count = 0
    for n in RUNGS:
        rungs = list(range(n))
        ok = ok and len(sector(n)) == 4 * n
        for i in range(n):
            for j in range(n):
                X = unit(n, i, j)
                for r, S, st in sector(n):
                    img = bilinear(X, rungs, st)
                    want = st_add(*[{mask([q] + [n + a for a in S]): X[q][r]} for q in range(n) if X[q][r]])
                    ok = ok and img == want
                    count += 1
    _tp_rv = (ok and count == 4 * (1 + 8 + 27)); assert _tp_rv is not False, "check_rung_mixing_is_the_ladder_action"; return _tp_rv


def check_pair_mixing_acts_on_the_spinor_factor():
    premise("rungs.rung-spinor-module-mixings")
    ok = True
    for n in RUNGS:
        pairs = [n, n + 1, n + 2]
        for a in range(3):
            for b in range(3):
                Y = unit(3, a, b)
                for r, S, st in sector(n):
                    img = bilinear(Y, pairs, st)
                    want = st_add(*[{mask([r] + [n + t for t in T]): c} for T, c in derive(Y, S).items()])
                    ok = ok and img == want
                    ok = ok and all(bin(m >> n).count("1") % 2 == 0 and bin(m & ((1 << n) - 1)).count("1") == 1
                                    for m in img)
    _tp_rv = (ok); assert _tp_rv is not False, "check_pair_mixing_acts_on_the_spinor_factor"; return _tp_rv

rungs.mass-bracket-frozen-points-grip-sl:
"""rungs.mass-bracket-frozen-points-grip-slot: exact checks over the Gaussian rationals (GA.QI), ported
from legacy verify_T12_rungs.py (lem:bracket) and widened (complex instances, the volume form computed
as a 4x4 determinant independently of the ambient pairing, the symmetric-square component).

Basis of CS = S_omega + S_pi: e1, e2, pi1, pi2 (the E = -1 and E = +1 eigenspaces of the grading
E = diag(-1, -1, 1, 1)), eps(e1 ^ e2 ^ pi1 ^ pi2) = 1, n_inf = e1 ^ e2, n_0 = pi1 ^ pi2.
  (1) eps(n_inf ^ Z1 ^ Z2) = <pi1 pi2>, eps(n_0 ^ Z1 ^ Z2) = <omega1 omega2>, and
      eps(I_Lambda ^ Z1 ^ Z2) = <pi1 pi2> + (Lambda/6) <omega1 omega2> (by the determinant, and equal to the
      ambient pairing); m^2 = 2 |eps(n_inf ^ Z1 ^ Z2)|^2 equals p^2 of the spinor momentum.
  (2) Psi = e1' (x) Z1 + e2' (x) Z2 in C^2 (x) CS: the slot trace of Psi (x) conj(Psi), restricted to the
      pi-block, is the total momentum; the Lambda^2 C^2 (x) Lambda^2 CS component of Psi (x) Psi is
      (1/2) (e1' ^ e2') (x) (Z1 ^ Z2).
  (3) At Lambda = 0 the mass vanishes exactly when Z1 ^ Z2 is orthogonal to n_inf (aligned pi parts).
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

# ---------------------------------------------------------------------------
# Twistor core (shared text, ported from legacy/verify_T11.py Parts B-D; self-contained).
# CS = C^4 with basis e1, e2 (omega-plane) and e3, e4 (pi-plane); the ambient space is
# Lambda^2 CS in the basis e_i ^ e_j (i < j), with n_inf = e1^e2, n_0 = e3^e4 and the pairing
# <P, P'> = coefficient of e1^e2^e3^e4 in P ^ P'. Everything is over the Gaussian rationals GA.QI.
# ---------------------------------------------------------------------------
from itertools import combinations as _comb

QZ = GA.qi(0)
QO = GA.qi(1)
PAIRS4 = list(_comb(range(4), 2))


def q(re, im=0):
    return GA.qi(re, im)


def eps2(a, b):
    """<ab> = a_0 b_1 - a_1 b_0."""
    return a[0] * b[1] - a[1] * b[0]


def wedge2(z1, z2):
    return [z1[i] * z2[j] - z1[j] * z2[i] for (i, j) in PAIRS4]


def perm_sign(perm):
    s, p = 1, list(perm)
    for i in range(len(p)):
        for j in range(i + 1, len(p)):
            if p[i] > p[j]:
                s = -s
    return s


def amb_pair(P, R):
    tot = QZ
    for a, (i, j) in enumerate(PAIRS4):
        if not P[a]:
            continue
        for b, (k, l) in enumerate(PAIRS4):
            if R[b] and len({i, j, k, l}) == 4:
                tot = tot + q(perm_sign((i, j, k, l))) * P[a] * R[b]
    return tot


def biv(i, j):
    out = [QZ] * 6
    out[PAIRS4.index((min(i, j), max(i, j)))] = QO if i < j else -QO
    return out


def vadd(*us):
    return [sum((u[k] for u in us), QZ) for k in range(len(us[0]))]


def vscal(c, u):
    return [c * a for a in u]


N_INF, N_0 = biv(0, 1), biv(2, 3)
EAMB = [biv(i, j) for (i, j) in PAIRS4]
X_SLOT = [biv(0, 2), biv(0, 3), biv(1, 2), biv(1, 3)]


def twistor(om, pi):
    return [om[0], om[1], pi[0], pi[1]]


def i_lam(lam):
    """I = n_inf + lam n_0 (lam = Lambda/6)."""
    return vadd(N_INF, vscal(q(lam), N_0))


def xslot(co):
    return vadd(*[vscal(q(c), v) for c, v in zip(co, X_SLOT)])


def xpoint(x):
    """X(x) = n_0 + x - (1/2) <x,x> n_inf."""
    return vadd(N_0, x, vscal(-amb_pair(x, x) / q(2), N_INF))


def on_line(co, pi):
    """The twistor (mu_x pi, pi) on the incidence line of x = (x13, x14, x23, x24)."""
    x13, x14, x23, x24 = co
    om = [-q(x13) * pi[1] + q(x14) * pi[0], -q(x23) * pi[1] + q(x24) * pi[0]]
    return twistor(om, pi)


def act(A, P):
    """A.(u^v) = Au^v + u^Av, extended linearly to bivectors."""
    out = [QZ] * 6
    for a, (i, j) in enumerate(PAIRS4):
        if not P[a]:
            continue
        Aei = [A[r][i] for r in range(4)]
        Aej = [A[r][j] for r in range(4)]
        ei = [QO if r == i else QZ for r in range(4)]
        ej = [QO if r == j else QZ for r in range(4)]
        out = vadd(out, vscal(P[a], vadd(wedge2(Aei, ej), wedge2(ei, Aej))))
    return out


def rot(U, V, W):
    """R_{U^V}(W) = <U,W> V - <V,W> U."""
    return vadd(vscal(amb_pair(U, W), V), vscal(-amb_pair(V, W), U))


def gsolve(rows, rhs):
    """Exact solution of a consistent (possibly overdetermined) system over Q(i)."""
    m, n = len(rows), len(rows[0])
    A = [rows[i][:] + [rhs[i]] for i in range(m)]
    piv, r = [], 0
    for c in range(n):
        p = next((i for i in range(r, m) if A[i][c]), None)
        if p is None:
            continue
        A[r], A[p] = A[p], A[r]
        inv = QO / A[r][c]
        A[r] = [x * inv for x in A[r]]
        for i in range(m):
            if i != r and A[i][c]:
                f = A[i][c]
                A[i] = [x - f * y for x, y in zip(A[i], A[r])]
        piv.append(c)
        r += 1
    if any(A[i][n] for i in range(r, m)):
        raise ValueError("inconsistent linear system")
    if len(piv) != n:
        raise ValueError("underdetermined linear system")
    sol = [QZ] * n
    for i, c in enumerate(piv):
        sol[c] = A[i][n]
    return sol


_UNIT_ACT = []


def _unit_act():
    if not _UNIT_ACT:
        for r in range(4):
            for c in range(4):
                A = [[QZ] * 4 for _ in range(4)]
                A[r][c] = QO
                _UNIT_ACT.append([act(A, EAMB[b]) for b in range(6)])
    return _UNIT_ACT


_SP = {}


def spin_preimage(U, V):
    """The traceless A in gl(4) whose action on Lambda^2 CS is the rotation R_{U^V} (memoised)."""
    key = tuple((c.re, c.im) for c in U + V)
    if key not in _SP:
        _SP[key] = _spin_preimage(U, V)
    return [row[:] for row in _SP[key]]


def _spin_preimage(U, V):
    ua = _unit_act()
    rows, rhs = [], []
    for b in range(6):
        target = rot(U, V, EAMB[b])
        for comp in range(6):
            rows.append([ua[k][b][comp] for k in range(16)])
            rhs.append(target[comp])
    rows.append([QO if r == c else QZ for r in range(4) for c in range(4)])
    rhs.append(QZ)
    sol = gsolve(rows, rhs)
    return [[sol[4 * r + c] for c in range(4)] for r in range(4)]


SIG = [[QO if abs(a - b) == 2 else QZ for b in range(4)] for a in range(4)]


def herm(zi, zj):
    """conj(zi)^T Sigma zj: the (2,2) Hermitian form pairing omega with conj(pi)."""
    return sum((zi[a].conj() * zj[b] for a in range(4) for b in range(4) if SIG[a][b]), QZ)


def moment(A, Zs):
    """M_A = i sum_i conj(Z_i)^T Sigma A Z_i."""
    tot = QZ
    for z in Zs:
        Az = [sum((A[r][c] * z[c] for c in range(4)), QZ) for r in range(4)]
        tot = tot + herm(z, Az)
    return GA.QI_I * tot


def gram_inverse(basis):
    n = len(basis)
    Gs = [[amb_pair(u, v) for v in basis] for u in basis]
    cols = [gsolve([row[:] for row in Gs], [QO if r == c else QZ for r in range(n)]) for c in range(n)]
    return [[cols[c][r] for c in range(n)] for r in range(n)]


_GI = []


def grip(Zs, I):
    """P = M(I): the ambient vector with <P, U> = M_{A(U ^ I)} for every U."""
    if not _GI:
        _GI.append(gram_inverse(EAMB))
    vals = [moment(spin_preimage(EAMB[a], I), Zs) for a in range(6)]
    P = [sum((vals[a] * _GI[0][a][J] for a in range(6)), QZ) for J in range(6)]
    assert all(amb_pair(P, EAMB[a]) == vals[a] for a in range(6))
    return P


def gram_h(Zs):
    return [[herm(a, b) for b in Zs] for a in Zs]


def internal_casimir(Z1, Z2):
    """C = (h11 - h22)^2/4 + |h12|^2 = tr(h_0^2)/2."""
    h11, h22, h12 = herm(Z1, Z1), herm(Z2, Z2), herm(Z1, Z2)
    return (h11 - h22) * (h11 - h22) / q(4) + h12 * h12.conj()


def casimir(Zs, basis):
    """C2(W) = (1/2) g^{ac} g^{bd} M_ab M_cd over the span of `basis`."""
    n = len(basis)
    Gi = gram_inverse(basis)
    Mm = [[moment(spin_preimage(u, v), Zs) if a != b else QZ for b, v in enumerate(basis)]
          for a, u in enumerate(basis)]
    tot = QZ
    for a in range(n):
        for b in range(n):
            if not Mm[a][b]:
                continue
            for c in range(n):
                if not Gi[a][c]:
                    continue
                for d in range(n):
                    if Gi[b][d] and Mm[c][d]:
                        tot = tot + Gi[a][c] * Gi[b][d] * Mm[a][b] * Mm[c][d]
    return tot / q(2)


def xreal(t, x_, y, z):
    """The real slice x = i K eps, K the Hermitian matrix of (t, x, y, z)."""
    K = [[q(t + z), q(x_, -y)], [q(x_, y), q(t - z)]]
    eps = [[QZ, QO], [-QO, QZ]]
    X = [[sum((K[a][b] * eps[b][c] for b in range(2)), QZ) * GA.QI_I for c in range(2)] for a in range(2)]
    return vadd(*[vscal(c_, v) for c_, v in zip((X[0][0], X[0][1], X[1][0], X[1][1]), X_SLOT)])


def in_su22(A):
    SA = [[sum((SIG[i][k] * A[k][j] for k in range(4)), QZ) for j in range(4)] for i in range(4)]
    return all(SA[i][j] + SA[j][i].conj() == QZ for i in range(4) for j in range(4))

INST = [
    ([q(2), q(-1), q(3), q(5)], [q(1), q(4), q(-2), q(7)]),
    ([q(F(1, 2)), q(3), q(-1), q(F(2, 3))], [q(5), q(-2), q(4), q(1)]),
    ([q(1, 1), q(2), q(3, -1), q(F(1, 2))], [q(0, 2), q(-1), q(1, 1), q(2, 3)]),
    ([q(0), q(1, 4), q(1, 1), q(0)], [q(1), q(0), q(0), q(2, -1)]),
]
BASIS4 = [[q(1) if r == i else QZ for r in range(4)] for i in range(4)]


def det(M):
    if len(M) == 1:
        return M[0][0]
    return sum((q((-1) ** c) * M[0][c] * det([row[:c] + row[c + 1:] for row in M[1:]])
                for c in range(len(M)) if M[0][c]), QZ)


def eps_biv(I_terms, Z1, Z2):
    """eps(I ^ Z1 ^ Z2) for I = sum c (u ^ v), given as [(c, u, v)]: a 4x4 determinant per term."""
    return sum((c * det([u, v, Z1, Z2]) for c, u, v in I_terms), QZ)


def spinor_p2(p1, p2):
