rungs.r-s-are-one-hypothesis-two:
"""rungs.r-s-are-one-hypothesis-two: exact checks.

Two exact Jordan-Wigner Fock models of five modes (basis states are bitmasks, a state is
a^dag_(m1) ... a^dag_(mk) |0> with m1 < ... < mk): model R is Lambda(W + R_2) with the pairs as modes 0, 1, 2
and the rungs as modes 3, 4; model S is Lambda(C^2 + W) with the slots as modes 0, 1 and the pairs as 2, 3, 4.
The identification Phi sends slot i to rung i and is the canonical isomorphism of exterior algebras: the
R-state a^dag(P) a^dag(G)|0> goes to the S-state built by the same creation operators in the same order.
(1) Phi is bijective on basis states up to signs and intertwines every creation and annihilation operator
    (the two CAR systems are one), hence every generator of gl(2) + gl(3) (sum X a^dag a over rungs/slots
    and over pairs), the (j, k) grading and the chirality (-1)^N = (-1)^(j+k); the (j, k) pieces have
    dimension C(2, j) C(3, k), total 32.
(2) The j = 1 sector is C^2 (x) Lambda W with the slot mixing acting once (X (x) 1) and y-weight
    3j - 2k = 3 - 2k: the constituent space of (C); the even half has dimension 16 with the components
    (0,0), (0,2), (1,1), (1,3), (2,0), (2,2) of hypercharge (3j - 2k)/6 = 0, -2/3, 1/6, -1/2, 1, 1/3:
    nu^c, u^c, Q, L, e^c, d^c, the derived generation.
(3) The Bogoliubov algebra: the ten real Majorana combinations a + a^dag, a - a^dag satisfy the Clifford
    relations of signature (5, 5); the 45 bilinears gamma_p gamma_q (p < q) are orthogonal for the trace form
    (Gram 32 times the identity, so independent), commute with the chirality, and close under the commutator
    with the so(10) structure constants [g_a g_b, g_c g_d] = 2(n_bc g_a g_d - n_ac g_b g_d - n_bd g_a g_c +
    n_ad g_b g_c): Spin(10) (complexified) acting on each chirality half.
"""
from fractions import Fraction as F
from itertools import combinations

import GA  # noqa: F401
import fock
from tp_premise import premise

NM = 5
DIM = 2 ** NM
R_PAIRS, R_RUNGS = [0, 1, 2], [3, 4]
S_SLOTS, S_PAIRS = [0, 1], [2, 3, 4]


# a_i^dag, a_i on sparse Fock states {bitmask: coefficient} (LSB, Jordan-Wigner) and their sum, from lib/fock.py
cre, ann, st_add = fock.cre_on, fock.ann_on, fock.vadd


def bilinear(X, modes, st):
    """sum_rs X_rs a^dag_(modes r) a_(modes s) on a Fock state."""
    terms = []
    for r in range(len(modes)):
        for s in range(len(modes)):
            if X[r][s]:
                terms.append({b: X[r][s] * c for b, c in cre(modes[r], ann(modes[s], st)).items()})
    return st_add(*terms) if terms else {}


def mask(modes):
    return sum(1 << m for m in modes)


def comb(n, k):
    return len(list(combinations(range(n), k)))


def r_to_s_mode(m):
    return S_PAIRS[R_PAIRS.index(m)] if m in R_PAIRS else S_SLOTS[R_RUNGS.index(m)]


def phi(st):
    """The canonical identification on a state of model R."""
    out = {}
    for b, c in st.items():
        modes = [m for m in range(NM) if b >> m & 1]
        img = {0: c}
        for m in reversed(modes):
            img = cre(r_to_s_mode(m), img)
        for bb, cc in img.items():
            out[bb] = out.get(bb, 0) + cc
    return {b: c for b, c in out.items() if c}


def unit(n, i, j):
    return [[1 if (a, b) == (i, j) else 0 for b in range(n)] for a in range(n)]


def jk_s(b):
    return bin(b & 3).count("1"), bin(b >> 2).count("1")


def check_r_and_s_are_the_same_module():
    premise("rungs.rung-spinor-module-mixings")
    premise("rungs.imported-tower-one-qubit-per-rung")
    premise("rungs.ladder-group-rung-mixing-group-one")
    ok = True
    images = [phi({b: 1}) for b in range(DIM)]
    ok = ok and all(len(im) == 1 and abs(next(iter(im.values()))) == 1 for im in images)
    ok = ok and sorted(next(iter(im)) for im in images) == list(range(DIM))
    for b in range(DIM):
        st = {b: 1}
        for m in range(NM):
            ok = ok and phi(cre(m, st)) == cre(r_to_s_mode(m), phi(st))
            ok = ok and phi(ann(m, st)) == ann(r_to_s_mode(m), phi(st))
        jr = bin(b >> 3).count("1"), bin(b & 7).count("1")
        tgt = next(iter(images[b]))
        ok = ok and jk_s(tgt) == jr and bin(b).count("1") % 2 == sum(jr) % 2
        for i in range(2):
            for j in range(2):
                X = unit(2, i, j)
                ok = ok and phi(bilinear(X, R_RUNGS, st)) == bilinear(X, S_SLOTS, phi(st))
        for a in range(3):
            for c in range(3):
                Y = unit(3, a, c)
                ok = ok and phi(bilinear(Y, R_PAIRS, st)) == bilinear(Y, S_PAIRS, phi(st))
    counts = {}
    for b in range(DIM):
        counts[jk_s(b)] = counts.get(jk_s(b), 0) + 1
    ok = ok and counts == {(j, k): comb(2, j) * comb(3, k) for j in range(3) for k in range(4)}
    _tp_rv = (ok); assert _tp_rv is not False, "check_r_and_s_are_the_same_module"; return _tp_rv


def check_constituent_sector_and_generation():
    premise("rungs.ladder-group-rung-mixing-group-one")
    premise("standard-model.under-s-composites-state-space-spinor")
    ok = True
    for b in range(DIM):
        j, k = jk_s(b)
        y = st_add(bilinear([[3, 0], [0, 3]], S_SLOTS, {b: 1}), bilinear([[-2, 0, 0], [0, -2, 0], [0, 0, -2]], S_PAIRS, {b: 1}))
        ok = ok and y == ({b: 3 * j - 2 * k} if 3 * j - 2 * k else {})
        if j == 1:
            for i in range(2):
                for jj in range(2):
                    img = bilinear(unit(2, i, jj), S_SLOTS, {b: 1})
                    want = {(b & ~3) | (1 << i): 1} if (b & 3) == (1 << jj) else {}
                    ok = ok and img == want
    even = sorted({jk_s(b) for b in range(DIM) if bin(b).count("1") % 2 == 0})
    ok = ok and sum(1 for b in range(DIM) if bin(b).count("1") % 2 == 0) == 16
    ok = ok and even == [(0, 0), (0, 2), (1, 1), (1, 3), (2, 0), (2, 2)]
    ok = ok and [F(3 * j - 2 * k, 6) for j, k in even] == [F(0), F(-2, 3), F(1, 6), F(-1, 2), F(1), F(1, 3)]
    _tp_rv = (ok); assert _tp_rv is not False, "check_constituent_sector_and_generation"; return _tp_rv


def _op(f):
    """Sparse matrix of a linear map given on basis states: column b -> image state."""
    return {b: f({b: 1}) for b in range(DIM)}


def _apply(M, st):
    return st_add(*[{r: c * v for r, v in M[b].items()} for b, c in st.items()]) if st else {}


def _comp(A, B):
    return {b: _apply(A, B[b]) for b in range(DIM)}


def _lin(*terms):
    return {b: st_add(*[{r: c * v for r, v in M[b].items()} for c, M in terms]) for b in range(DIM)}


def check_bogoliubov_spin10():
    premise("rungs.imported-fock-representation-bogoliubov-group")
    premise("rungs.rung-spinor-module-mixings")
    ok = True
    gam, eta = [], []
    for m in range(NM):
        gam.append(_op(lambda st, m=m: st_add(cre(m, st), ann(m, st))))
        gam.append(_op(lambda st, m=m: st_add(ann(m, st), {b: -c for b, c in cre(m, st).items()})))
        eta += [1, -1]
    ident = {b: {b: 1} for b in range(DIM)}
    zero = {b: {} for b in range(DIM)}
    for p in range(10):
        for q in range(10):
            anti = _lin((1, _comp(gam[p], gam[q])), (1, _comp(gam[q], gam[p])))
            ok = ok and anti == (_lin((2 * eta[p], ident)) if p == q else zero)
    pairs = list(combinations(range(10), 2))
    L = {pq: _comp(gam[pq[0]], gam[pq[1]]) for pq in pairs}
    gram = {}
    for pq in pairs:
        for rs in pairs:
            gram[(pq, rs)] = sum(c * L[rs][b].get(r, 0) for b in range(DIM) for r, c in L[pq][b].items())
    ok = ok and all(gram[(pq, rs)] == (DIM if pq == rs else 0) for pq in pairs for rs in pairs)
    chir = {b: {b: -1 if bin(b).count("1") % 2 else 1} for b in range(DIM)}
    ok = ok and all(_comp(L[pq], chir) == _comp(chir, L[pq]) for pq in pairs)

    def Lg(a, b):
        if a == b:
            return zero
        return L[(a, b)] if a < b else _lin((-1, L[(b, a)]))

    def d(x, y):
        return eta[x] if x == y else 0
    for (a, b) in pairs:
        for (c, e) in pairs:
            lhs = _lin((1, _comp(L[(a, b)], L[(c, e)])), (-1, _comp(L[(c, e)], L[(a, b)])))
            rhs = _lin((2 * d(b, c), Lg(a, e)), (-2 * d(a, c), Lg(b, e)), (-2 * d(b, e), Lg(a, c)), (2 * d(a, e), Lg(b, c)))
            ok = ok and lhs == rhs
    _tp_rv = (ok and len(pairs) == 45); assert _tp_rv is not False, "check_bogoliubov_spin10"; return _tp_rv

rungs.rung-spinor-module-mixings:
"""rungs.rung-spinor-module-mixings: exact checks.

The complexified spinor module of the n-th rung Cl(2+n, 4+n) (n = 0..3) as a Fock space over Q(i)
(GA.QI): m = 3 + n modes, modes 0..n-1 the new rung modes (R_n), modes n..n+2 the old modes (W).
States are bitmasks; a_i is the Jordan-Wigner annihilator. Operators are sparse matrices
{column: {row: QI}}. The real generators: for the old modes n, n+1 and every new mode a real
hyperbolic pair e = a^dag + a (square +1), f = a^dag - a (square -1); for the old mode n+2 two negative
generators g1 = i(a + a^dag), g2 = a - a^dag (both square -1). That is 2+n positive and 4+n negative
generators: the complexification of Cl(2+n, 4+n). Majoranas gamma_{2i} = a_i + a_i^dag,
gamma_{2i+1} = i(a_i - a_i^dag).
(1) The 6+2n generators satisfy the relations of Cl(2+n,4+n) on every state; dim = 2^(3+n) = 8, 16, 32,
    64; the vacuum spans the common kernel of the annihilators and the creation monomials on it span
    the module (so it is irreducible); the bigraded pieces have dimension C(n,j) C(3,k); the product
    of all generators acts as a scalar times (-1)^(j+k) (chirality = parity of j + k); at n = 2 the
    module has 5 modes and its halves have dimension 16.
(2) Block unitaries B (+) A (rational unitaries over Q(i), B on W, A on R_n) act by Lambda(B (+) A): the
    operator with matrix entries the minors det(U[T,S]) is unitary, preserves every piece
    Lambda^j R_n (x) Lambda^k W, and is Bogoliubov-covariant: Lambda(U) a_i^dag = sum_l U_li a_l^dag Lambda(U).
(3) The Majoranas are Hermitian, square to 1 and anticommute: a Euclidean Clifford algebra on 6+2n
    generators. The bilinears gamma_p gamma_q (p < q) act on span(gamma) by real matrices (on the Fock
    space for n <= 2, each commutator confirmed to be a real combination of the gammas; in GA.py's
    Cl(6+2n, 0) for every n) spanning a space of dimension 15, 28, 45, 66 = dim so(6+2n); for n <= 1 a
    rational rotor c + s gamma_p gamma_q (c^2 + s^2 = 1) is unitary and rotates span(gamma) orthogonally. At n = 2 each chirality half has a
    one-dimensional common kernel for the lowering operators of so(10) (a_i a_j and a_j^dag a_i,
    i < j), so Spin(10) acts irreducibly on each half (complete reducibility imported). Number
    preserving: for a sample X in u(m), phi(X) = (1/2) sum X_ij [a_i^dag, a_j] (quadratic in the
    Majoranas) equals dGamma(X) - (tr X / 2) 1, acts on a_k^dag as X does (the Lambda (x) det^(-1/2) action) and agrees with dGamma(X) when
    tr X = 0; the double cover: (gamma_{2i} gamma_{2i+1})^2 = -1 while conjugation by it negates a_i^dag
    only, so -1 in Spin covers the identity of U.
(4) At n = 3, u(3) (+) u(3) (18 generators) acts faithfully on the module (rank 18 on the one-mode
    sector), acts on the cell sector Lambda^1 R_3 (x) Lambda^1 W with rank 17, its kernel generator
    (i I, -i I) has eigenvalue i(j - k) on each piece (zero exactly on the cells) and is trace-free, and
    the trace-free subalgebra (17) acts on the cells with rank 16; at n = 2 u(2) (+) u(3) (13) acts on
    the cells with rank 12, the kernel generator is not trace-free, and s(u(2) (+) u(3)) (12) acts with
    rank 12. The counts 2^(3+n), dim so(6+2n) and dim(u(3) (+) u(n)) = 9 + n^2 are the computed
    dimensions and ranks.
Not computed: the identification with Hypothesis (S) beyond the shape of the module and action, and
the global (group-level) faithfulness beyond the Lie algebra.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from pyutil import get_or_set
from tp_premise import premise

QI = GA.QI
I_ = QI(0, 1)
ZERO = QI(0)


# ---- sparse operators over Q(i) ----
def op_add(*ops):
    out = {}
    for A in ops:
        for c, col in A.items():
            d = get_or_set(out, c, {})
            for r, v in col.items():
                d[r] = d.get(r, ZERO) + v
    return {c: {r: v for r, v in col.items() if v} for c, col in out.items() if any(col.values())}


def op_scal(z, A):
    z = QI._co(z)
    return {c: {r: v * z for r, v in col.items()} for c, col in A.items()} if z else {}


def op_mul(A, B):
    out = {}
    for c, colB in B.items():
        acc = {}
        for k, y in colB.items():
            for r, x in A.get(k, {}).items():
                acc[r] = acc.get(r, ZERO) + x * y
        acc = {r: v for r, v in acc.items() if v}
        if acc:
            out[c] = acc
    return out


def op_eq(A, B):
    return op_add(A, op_scal(-1, B)) == {}


def op_dag(A):
    out = {}
    for c, col in A.items():
        for r, v in col.items():
            get_or_set(out, r, {})[c] = v.conj()
    return out


def ident(dim):
    return {s: {s: QI(1)} for s in range(dim)}


def annih(i, m):
    out = {}
    for b in range(2 ** m):
        if b >> i & 1:
            sign = (-1) ** bin(b & ((1 << i) - 1)).count("1")
            out[b] = {b ^ (1 << i): QI(sign)}
    return out


class Fock(object):
    def __init__(self, n):
        self.n, self.m = n, 3 + n
        self.dim = 2 ** self.m
        self.a = [annih(i, self.m) for i in range(self.m)]
        self.ad = [op_dag(x) for x in self.a]
        self.one = ident(self.dim)

    def jk(self, b):
        return (sum(b >> i & 1 for i in range(self.n)), sum(b >> i & 1 for i in range(self.n, self.m)))

    def generators(self):
        """(operator, square) for the 6 + 2n real generators of Cl(2+n, 4+n)."""
        gens = []
        real = list(range(self.n)) + [self.n, self.n + 1]
        for i in real:
            gens.append((op_add(self.ad[i], self.a[i]), 1))
            gens.append((op_add(self.ad[i], op_scal(-1, self.a[i])), -1))
        c = self.n + 2
        gens.append((op_scal(I_, op_add(self.a[c], self.ad[c])), -1))
        gens.append((op_add(self.a[c], op_scal(-1, self.ad[c])), -1))
        return gens

    def majoranas(self):
        out = []
        for i in range(self.m):
            out.append(op_add(self.a[i], self.ad[i]))
            out.append(op_scal(I_, op_add(self.a[i], op_scal(-1, self.ad[i]))))
        return out

    def dgamma(self, X):
        """sum_ij X_ij a_i^dag a_j for an m x m matrix X of QI."""
        terms = [op_scal(X[i][j], op_mul(self.ad[i], self.a[j]))
                 for i in range(self.m) for j in range(self.m) if X[i][j]]
        return op_add(*terms) if terms else {}


def kernel_dim(ops, states, dim):
    """Dimension of the common kernel, inside span(states), of the given operators."""
    rows = []
    for A in ops:
        for r in range(dim):
            rows.append([A.get(s, {}).get(r, ZERO) for s in states])
    return len(states) - GA.field_rank(rows) if rows else len(states)


def u_basis(k):
    """Real basis of u(k) as k x k matrices of QI."""
    out = []
    for i in range(k):
        out.append([[I_ if (r, c) == (i, i) else ZERO for c in range(k)] for r in range(k)])
    for i, j in combinations(range(k), 2):
        out.append([[QI(1) if (r, c) == (i, j) else (QI(-1) if (r, c) == (j, i) else ZERO)
                     for c in range(k)] for r in range(k)])
        out.append([[I_ if (r, c) in ((i, j), (j, i)) else ZERO for c in range(k)] for r in range(k)])
    return out


def block(XW, XR, n):
    """The block matrix acting by XR on modes 0..n-1 (R_n) and XW on modes n..n+2 (W)."""
    m = 3 + n
    M = [[ZERO] * m for _ in range(m)]
    for r in range(n):
        for c in range(n):
            M[r][c] = XR[r][c]
    for r in range(3):
        for c in range(3):
            M[n + r][n + c] = XW[r][c]
    return M


def real_rank(ops, states):
    rows = []
    for A in ops:
        v = []
        for s in states:
            for t in states:
                z = A.get(s, {}).get(t, ZERO)
                v.extend([z.re, z.im])
        rows.append(v)
    return GA.rank_of_vectors(rows)


def check_spinor_module_irreducible_graded():
    premise("rungs.imported-tower-one-qubit-per-rung")
    premise("rungs.imported-spinor-identification-witt-data-line")
    for n in range(4):
        fk = Fock(n)
        gens = fk.generators()
        assert len(gens) == 6 + 2 * n
        assert sum(1 for _, s in gens if s == 1) == 2 + n
        for i, (x, sx) in enumerate(gens):
            assert op_eq(op_mul(x, x), op_scal(sx, fk.one))
            for y, _ in gens[i + 1:]:
                assert op_add(op_mul(x, y), op_mul(y, x)) == {}
        assert fk.dim == 2 ** (3 + n)
        states = list(range(fk.dim))
        assert kernel_dim(fk.a, states, fk.dim) == 1
        assert all(fk.a[i].get(0) is None for i in range(fk.m))
        imgs = []
        for b in states:
            v = {0: QI(1)}
            for i in reversed([i for i in range(fk.m) if b >> i & 1]):
                v = {r: x for r, x in op_mul(fk.ad[i], {0: v}).get(0, {}).items()}
            imgs.append([v.get(r, ZERO) for r in states])
        assert GA.field_rank(imgs) == fk.dim
        counts = {}
        for b in states:
            counts[fk.jk(b)] = counts.get(fk.jk(b), 0) + 1
        for (j, k), c in counts.items():
            assert c == len(list(combinations(range(n), j))) * len(list(combinations(range(3), k)))
        vol = fk.one
        for x, _ in gens:
            vol = op_mul(vol, x)
        c0 = vol[0][0]
        for b in states:
            j, k = fk.jk(b)
            assert vol[b] == {b: c0 * (-1) ** (j + k)}
        if n == 2:
            assert fk.m == 5 and sum(1 for b in states if sum(fk.jk(b)) % 2 == 0) == 16
    return True


def cayley_unitary(H):
    """(1 + i H)(1 - i H)^{-1} for a Hermitian H over Q(i): a rational unitary."""
    k = len(H)
    P = [[(QI(1) if r == c else ZERO) + I_ * H[r][c] for c in range(k)] for r in range(k)]
    Mm = [[(QI(1) if r == c else ZERO) - I_ * H[r][c] for c in range(k)] for r in range(k)]
    cols = [GA.field_solve(Mm, [QI(1) if r == c else ZERO for r in range(k)]) for c in range(k)]
    Minv = [[cols[c][r] for c in range(k)] for r in range(k)]
    return GA.field_mat_mul(P, Minv)


def det(Mx):
    if not Mx:
        return QI(1)
    tot = ZERO
    for c in range(len(Mx)):
        minor = [row[:c] + row[c + 1:] for row in Mx[1:]]
        if Mx[0][c]:
            tot = tot + Mx[0][c] * det(minor) * (-1) ** c
    return tot


def lambda_op(U, m):
    out = {}
    for S in range(2 ** m):
        sl = [i for i in range(m) if S >> i & 1]
        col = {}
        for T in range(2 ** m):
            tl = [i for i in range(m) if T >> i & 1]
            if len(tl) != len(sl):
                continue
            z = det([[U[r][c] for c in sl] for r in tl])
            if z:
                col[T] = z
        out[S] = col
    return out


HW = [[QI(1), QI(0, 2), ZERO], [QI(0, -2), QI(-1), QI(1)], [ZERO, QI(1), QI(3)]]
HR = {1: [[QI(2)]], 2: [[QI(0), QI(1, 1)], [QI(1, -1), QI(2)]],
      3: [[QI(1), ZERO, QI(0, 1)], [ZERO, QI(-2), QI(1)], [QI(0, -1), QI(1), ZERO]]}


def check_split_unitaries_act_by_exterior_powers():
    premise("rungs.imported-fock-representation-bogoliubov-group")
    for n in (1, 2, 3):
        fk = Fock(n)
        B, A = cayley_unitary(HW), cayley_unitary(HR[n])
        U = block(B, A, n)
        Ud = [[U[c][r].conj() for c in range(fk.m)] for r in range(fk.m)]
        assert GA.field_mat_mul(Ud, U) == [[QI(1) if r == c else ZERO for c in range(fk.m)]
                                           for r in range(fk.m)]
        L = lambda_op(U, fk.m)
        assert op_eq(op_mul(op_dag(L), L), fk.one)
        for S, col in L.items():
            for T in col:
                assert fk.jk(T) == fk.jk(S)
        for i in range(fk.m):
            lhs = op_mul(L, fk.ad[i])
            rhs = op_add(*[op_scal(U[l][i], op_mul(fk.ad[l], L)) for l in range(fk.m) if U[l][i]])
            assert op_eq(lhs, rhs)
    return True


def check_majoranas_and_bogoliubov_dimension():
    premise("rungs.imported-fock-representation-bogoliubov-group")
    premise("rungs.imported-tower-one-qubit-per-rung")
    for n in range(4):
        fk = Fock(n)
        gam = fk.majoranas()
        N = len(gam)
        for p in range(N):
            assert op_eq(op_dag(gam[p]), gam[p]) and op_eq(op_mul(gam[p], gam[p]), fk.one)
            for q in range(p + 1, N):
                assert op_add(op_mul(gam[p], gam[q]), op_mul(gam[q], gam[p])) == {}
        # adjoint action of the bilinears on span(gamma), on the Fock space for n <= 2: read the
        # gamma-coefficients off the vacuum column (gamma_2i |0> = |i>, gamma_2i+1 |0> = -i |i>),
        # confirming each commutator is exactly that real combination
        if n <= 2:
            mats = []
            for p, q in combinations(range(N), 2):
                Bpq = op_mul(gam[p], gam[q])
                row = []
                for r in range(N):
                    cm = op_add(op_mul(Bpq, gam[r]), op_scal(-1, op_mul(gam[r], Bpq)))
                    v0 = cm.get(0, {})
                    cf = []
                    for i in range(fk.m):
                        z = v0.get(1 << i, ZERO)
                        cf.extend([z.re, -z.im])
                    rebuilt = op_add(*[op_scal(cf[t], gam[t]) for t in range(N) if cf[t]]) if any(cf) else {}
                    assert op_eq(cm, rebuilt)
                    row.extend(cf)
                mats.append(row)
            assert GA.rank_of_vectors(mats) == N * (N - 1) // 2
        # the same algebra is Cl(N, 0) (the relations above): ranks in GA.py for every n
        SE = tuple([1] * N)
        mats = []
        for p, q in combinations(range(N), 2):
            Bpq = GA.mul(GA.gen(p), GA.gen(q), SE)
            row = []
            for r in range(N):
                cm = GA.sub(GA.mul(Bpq, GA.gen(r), SE), GA.mul(GA.gen(r), Bpq, SE))
                assert all(len(b) == 1 for b in cm)
                row.extend(cm.get((t,), F(0)) for t in range(N))
            mats.append(row)
        assert GA.rank_of_vectors(mats) == N * (N - 1) // 2 == [15, 28, 45, 66][n]
    return True


def check_number_preserving_part_and_double_cover():
    premise("rungs.imported-fock-representation-bogoliubov-group")
    for n in range(4):
        fk = Fock(n)
        gam = fk.majoranas()
        N = len(gam)
        if n <= 1:
            R = op_add(op_scal(F(3, 5), fk.one), op_scal(F(4, 5), op_mul(gam[0], gam[N - 1])))
            assert op_eq(op_mul(op_dag(R), R), fk.one)
            img = op_mul(op_mul(R, gam[0]), op_dag(R))
            assert op_eq(img, op_add(op_scal(F(-7, 25), gam[0]), op_scal(F(-24, 25), gam[N - 1])))
        # number-preserving part: phi(X) = (1/2) sum X_ij [a_i^dag, a_j] = dGamma(X) - tr(X)/2
        X = [[ZERO] * fk.m for _ in range(fk.m)]
        X[0][0], X[0][1], X[1][0], X[fk.m - 1][fk.m - 1] = I_, QI(2, 1), QI(-2, 1), QI(0, 3)
        phi = op_add(*[op_scal(X[i][j] * F(1, 2),
                               op_add(op_mul(fk.ad[i], fk.a[j]), op_scal(-1, op_mul(fk.a[j], fk.ad[i]))))
                       for i in range(fk.m) for j in range(fk.m) if X[i][j]])
        trX = sum((X[i][i] for i in range(fk.m)), ZERO)
        assert op_eq(phi, op_add(fk.dgamma(X), op_scal(trX * F(-1, 2), fk.one)))
        for k in range(fk.m):
            cm = op_add(op_mul(phi, fk.ad[k]), op_scal(-1, op_mul(fk.ad[k], phi)))
            want = op_add(*[op_scal(X[i][k], fk.ad[i]) for i in range(fk.m) if X[i][k]]) \
                if any(X[i][k] for i in range(fk.m)) else {}
            assert op_eq(cm, want)
        # double cover: (gamma_0 gamma_1)^2 = -1, and conjugation by it negates a_0^dag only
        g01 = op_mul(gam[0], gam[1])
        assert op_eq(op_mul(g01, g01), op_scal(-1, fk.one))
        ginv = op_scal(-1, g01)
        for k in range(fk.m):
            conj = op_mul(op_mul(g01, fk.ad[k]), ginv)
            assert op_eq(conj, op_scal(-1 if k == 0 else 1, fk.ad[k]))
    return True


def check_spin10_irreducible_on_each_half():
    premise("rungs.imported-fock-representation-bogoliubov-group")
    fk = Fock(2)
    low = []
    for i, j in combinations(range(fk.m), 2):
        low.append(op_mul(fk.a[i], fk.a[j]))
        low.append(op_mul(fk.ad[j], fk.a[i]))
    for parity in (0, 1):
        half = [b for b in range(fk.dim) if sum(fk.jk(b)) % 2 == parity]
        assert len(half) == 16
        assert kernel_dim(low, half, fk.dim) == 1
    return True


def check_cell_action_ranks_and_faithfulness():
    premise("rungs.imported-ladder-automorphism-group-no-lepton")
    for n in (2, 3):
        fk = Fock(n)
        gensW = [block(X, [[ZERO] * n for _ in range(n)], n) for X in u_basis(3)]
        gensR = [block([[ZERO] * 3 for _ in range(3)], X, n) for X in u_basis(n)]
        gens = gensW + gensR
        assert len(gens) == 9 + n * n
        ops = [fk.dgamma(X) for X in gens]
        one_mode = [1 << i for i in range(fk.m)]
        assert real_rank(ops, one_mode) == 9 + n * n
        cells = [b for b in range(fk.dim) if fk.jk(b) == (1, 1)]
        assert len(cells) == 3 * n
        full = real_rank(ops, cells)
        # trace-free subalgebra: off-diagonal generators plus trace-free diagonal combinations
        diag = [k for k, X in enumerate(gens) if sum((X[i][i] for i in range(fk.m)), ZERO)]
        rest = [ops[k] for k in range(len(gens)) if k not in diag]
        d0 = diag[0]
        tf = rest + [op_add(ops[d0], op_scal(-1, ops[k])) for k in diag[1:]]
        assert len(tf) == 8 + n * n
        tfr = real_rank(tf, cells)
        Kmat = block([[-I_ if r == c else ZERO for c in range(3)] for r in range(3)],
                     [[I_ if r == c else ZERO for c in range(n)] for r in range(n)], n)
        Kgen = fk.dgamma(Kmat)
        for b in range(fk.dim):
            j, k = fk.jk(b)
            assert Kgen.get(b, {}) == ({b: I_ * (j - k)} if j != k else {})
        trK = sum((Kmat[i][i] for i in range(fk.m)), ZERO)
        if n == 3:
            assert (full, tfr) == (17, 16) and trK == ZERO
        else:
            assert (full, tfr) == (12, 12) and trK != ZERO
    return True

rungs.transported-module-holds-tuple-one:
"""rungs.transported-module-holds-tuple-one-vector: exact checks.

The two-rung module as the five-mode Jordan-Wigner Fock model (rungs = modes 0, 1; pairs = modes 2, 3, 4;
exact integer signs), with the rung mixing sum X a^dag a over the rungs, the pair mixing over the pairs, the
y-generator 3 N_rung - 2 N_pair, and the su(2), sl(3) Casimirs C2 = EF + FE + H^2/2 (rungs) and
C3 = sum_ab E_ab E_ba - N_pair^2/3 (pairs).
(1) The sector (j, k) in {(1, 0), (1, 2)} is C^2 (x) CS, CS = Lambda^even W: dimension 8; the rung mixing acts
    on it as X (x) 1 on the slot index; y = 3 on (1, 0) and -1 on (1, 2) (Y = 1/2, -1/6); C2 = 3/2 (doublet)
    on both; C3 = 0 on (1, 0) and 8/3 on (1, 2), whose pair-torus weights are e_a + e_b (the 3b): the
    content (2,1)_{1/2} + (2,3b)_{-1/6} = L* + Q*.
(2) CS (x) CS is not equivariantly inside the module: the sl(3) Casimir takes only the values 0 and 8/3 on the
    whole module (contents 1, 3, 3b), while S^2(Lambda^2 W) (the symmetric square of the pair-torus action on
    Lambda^2 W, dimension 6 by exact rank) has Casimir 20/3 (the 6b) and contains the weights 2(e_a + e_b),
    whose sl(3) classes are not weights of the module (all of whose weights have coordinates in {0, 1}).
(3) The mass bracket Z^1 ^ Z^2 (the Lambda^2 C^2 (x) Lambda^2 CS component of Psi . Psi) is quadratic in Psi:
    B(c Psi) = c^2 B(Psi) and B is not additive, so no linear map from the module produces it; in the chart
    (e1, e2, pi1, pi2) its pairing with n_inf = e1 ^ e2 is <pi^1 pi^2>, exactly (samples over Q(i)).
"""
from fractions import Fraction as F
from itertools import combinations

import GA
import fock
from tp_premise import premise

RUNGS, PAIRS = [0, 1], [2, 3, 4]
DIM = 32
PSI_SAMPLES = [([GA.qi(1), GA.qi(2, -1), GA.qi(0, 1), GA.qi(3)], [GA.qi(-1, 1), GA.qi(0), GA.qi(2), GA.qi(1, 4)]),
               ([GA.qi(F(1, 2)), GA.qi(1, 1), GA.qi(-2), GA.qi(0, -3)], [GA.qi(5), GA.qi(-1, 2), GA.qi(1, 1), GA.qi(2)])]


# a_i^dag, a_i on sparse Fock states {bitmask: coefficient} (LSB, Jordan-Wigner) and their sum, from lib/fock.py
cre, ann, st_add = fock.cre_on, fock.ann_on, fock.vadd


def bilinear(X, modes, st):
    """sum_rs X_rs a^dag_(modes r) a_(modes s) on a Fock state."""
    terms = []
    for r in range(len(modes)):
        for s in range(len(modes)):
            if X[r][s]:
                terms.append({b: X[r][s] * c for b, c in cre(modes[r], ann(modes[s], st)).items()})
    return st_add(*terms) if terms else {}


def mask(modes):
    return sum(1 << m for m in modes)


def unit(n, i, j):
    return [[1 if (a, b) == (i, j) else 0 for b in range(n)] for a in range(n)]


def jk(b):
    return bin(b & 3).count("1"), bin(b >> 2).count("1")


scal = fock.vsc


def casimir2(st):
    E, Fm, H = unit(2, 0, 1), unit(2, 1, 0), [[1, 0], [0, -1]]
    ef = bilinear(E, RUNGS, bilinear(Fm, RUNGS, st))
    fe = bilinear(Fm, RUNGS, bilinear(E, RUNGS, st))
    hh = bilinear(H, RUNGS, bilinear(H, RUNGS, st))
    return st_add(scal(F(1), ef), scal(F(1), fe), scal(F(1, 2), hh))


def casimir3(st, act=None):
    act = act or (lambda Y, s: bilinear(Y, PAIRS, s))
    terms = []
    for a in range(3):
        for b in range(3):
            terms.append(scal(F(1), act(unit(3, a, b), act(unit(3, b, a), st))))
    Nst = act([[1, 0, 0], [0, 1, 0], [0, 0, 1]], st)
    terms.append(scal(F(-1, 3), act([[1, 0, 0], [0, 1, 0], [0, 0, 1]], Nst)))
    return st_add(*terms)


def check_two_spinor_configuration_is_the_one_rung_sector():
    premise("rungs.rung-spinor-module-mixings")
    premise("rungs.ladder-group-rung-mixing-group-one")
    premise("standard-model.under-s-composites-state-space-spinor")
    ok = True
    sector = [b for b in range(DIM) if jk(b) in ((1, 0), (1, 2))]
    ok = ok and len(sector) == 8
    weights02 = []
    for b in sector:
        j, k = jk(b)
        st = {b: 1}
        y = st_add(bilinear([[3, 0], [0, 3]], RUNGS, st), bilinear([[-2, 0, 0], [0, -2, 0], [0, 0, -2]], PAIRS, st))
        ok = ok and y == {b: 3 * j - 2 * k}
        ok = ok and casimir2(st) == {b: F(3, 2)}
        ok = ok and casimir3(st) == ({b: F(8, 3)} if k == 2 else {})
        for i in range(2):
            for jj in range(2):
                want = {(b & ~3) | (1 << i): 1} if (b & 3) == (1 << jj) else {}
                ok = ok and bilinear(unit(2, i, jj), RUNGS, st) == want
        if k == 2:
            weights02.append(tuple((b >> m) & 1 for m in PAIRS))
    ok = ok and sorted(set(weights02)) == [(0, 1, 1), (1, 0, 1), (1, 1, 0)]
    ok = ok and [F(3 * 1 - 2 * k, 6) for k in (0, 2)] == [F(1, 2), F(-1, 6)]
    _tp_rv = (ok); assert _tp_rv is not False, "check_two_spinor_configuration_is_the_one_rung_sector"; return _tp_rv


def _sym_square_states():
    """S^2(Lambda^2 W): symmetric tensors f_S (x) f_T + f_T (x) f_S, |S| = |T| = 2."""
    L2 = list(combinations(range(3), 2))
    out = []
    for i, S in enumerate(L2):
        for T in L2[i:]:
            st = {(S, T): 1}
            st[(T, S)] = st.get((T, S), 0) + 1
            out.append(st)
    return out


def _derive(Y, S):
    out = {}
    for t, s in enumerate(S):
        for r in range(3):
            if Y[r][s]:
                seq = S[:t] + (r,) + S[t + 1:]
                if len(set(seq)) < len(seq):
                    continue
                sign = 1
                lst = list(seq)
                for i in range(len(lst)):
                    for j in range(len(lst) - 1 - i):
                        if lst[j] > lst[j + 1]:
                            lst[j], lst[j + 1] = lst[j + 1], lst[j]
                            sign = -sign
                T = tuple(lst)
                out[T] = out.get(T, 0) + sign * Y[r][s]
    return {T: c for T, c in out.items() if c}


def _tensor_act(Y, st):
    out = {}
    for (S, T), c in st.items():
        for S2, d in _derive(Y, S).items():
            out[(S2, T)] = out.get((S2, T), 0) + c * d
        for T2, d in _derive(Y, T).items():
            out[(S, T2)] = out.get((S, T2), 0) + c * d
    return {k: v for k, v in out.items() if v}


def check_two_particle_product_not_in_module():
    premise("rungs.rung-spinor-module-mixings")
    ok = True
    module_cas = set()
    for b in range(DIM):
        c = casimir3({b: 1})
        vals = set(c.values()) if c else {F(0)}
        ok = ok and (not c or set(c) == {b})
        module_cas |= vals
    ok = ok and module_cas == {F(0), F(8, 3)}
    sym = _sym_square_states()
    keys = sorted({K for st in sym for K in st})
    ok = ok and GA.rank_of_vectors([[F(st.get(K, 0)) for K in keys] for st in sym]) == 6
    for st in sym:
        cas = casimir3(st, act=_tensor_act)
        ok = ok and cas == {K: F(20, 3) * v for K, v in st.items()}

    def sl3(w):
        m = F(sum(w), 3)
        return tuple(F(x) - m for x in w)
    module_classes = {sl3(tuple((b >> m) & 1 for m in PAIRS)) for b in range(DIM)}
    doubled = [tuple(2 * (i in S) for i in range(3)) for S in combinations(range(3), 2)]
    ok = ok and all(sl3(w) not in module_classes for w in doubled)
    _tp_rv = (ok); assert _tp_rv is not False, "check_two_particle_product_not_in_module"; return _tp_rv


def check_mass_bracket_is_quadratic():
    premise("rungs.mass-bracket-frozen-points-grip-slot")

    def wedge(Z1, Z2):
        return {(a, b): Z1[a] * Z2[b] - Z1[b] * Z2[a] for a, b in combinations(range(4), 2)}

    def det4(cols):
        """Exact determinant over Q(i) by Laplace expansion along the first column."""
        M = [[cols[c][r] for c in range(len(cols))] for r in range(len(cols))]

        def det(A):
            if len(A) == 1:
                return A[0][0]
            tot = GA.qi(0)
            for r in range(len(A)):
                minor = [row[1:] for i, row in enumerate(A) if i != r]
                term = A[r][0] * det(minor)
                tot = tot + term if r % 2 == 0 else tot - term
            return tot
        return det(M)
    E = [[GA.qi(1 if i == j else 0) for i in range(4)] for j in range(4)]   # chart basis e1, e2, pi1, pi2
    ok = det4(E) == GA.qi(1)

    for Z1, Z2 in PSI_SAMPLES:
        B = wedge(Z1, Z2)
        ok = ok and det4([E[0], E[1], Z1, Z2]) == Z1[2] * Z2[3] - Z1[3] * Z2[2]      # <pi^1 pi^2>
        ok = ok and det4([E[2], E[3], Z1, Z2]) == Z1[0] * Z2[1] - Z1[1] * Z2[0]      # <omega^1 omega^2>
        c = GA.qi(2, 1)
        Bc = wedge([c * z for z in Z1], [c * z for z in Z2])
        ok = ok and all(Bc[K] == c * c * B[K] for K in B) and any(Bc[K] != c * B[K] for K in B)
    (A1, A2), (C1, C2) = PSI_SAMPLES
    Bs = wedge([a + c for a, c in zip(A1, C1)], [a + c for a, c in zip(A2, C2)])
    BA, BC = wedge(A1, A2), wedge(C1, C2)
    ok = ok and any(Bs[K] != BA[K] + BC[K] for K in Bs)
    _tp_rv = (ok); assert _tp_rv is not False, "check_mass_bracket_is_quadratic"; return _tp_rv

